describe('BillingService billing report processing', () => {
    const CUSTOMER_ID = 'de4b5cd2-6f0c-4f2d-9b0e-6a1b4c8f3a11';
    const BUSINESS_ID = 'myCoolCorp';

    let point;
    let influxService;
    let customerService;
    let invoicesService;
    let service: BillingService;
    let publishEvent: jest.SpyInstance;

    const buildJob = (data: Partial<SchedulerEntity>) => ({ data } as Job<SchedulerEntity>);

    beforeEach(() => {
        point = { tag: jest.fn(() => point), stringField: jest.fn(() => point) };
        influxService = { getPoint: jest.fn(() => point), loadPoints: jest.fn() };
        customerService = {
            findOne: jest.fn().mockResolvedValue({
                data: [{ customerId: CUSTOMER_ID, offering: { billingCycle: validBillingCycles.monthly } }],
                message: 'Found Customer',
            }),
        };
        invoicesService = { generateInvoiceForUsageTotal: jest.fn().mockResolvedValue({ invoiceId: 'invoice-1' }) };
        publishEvent = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
        service = new BillingService(
            influxService as unknown as InfluxService,
            customerService as unknown as CustomerService,
            invoicesService as unknown as InvoicesService
        );
    });

    afterEach(() => {
        jest.restoreAllMocks();
    });

    it('invoices the customer of the schedule for the billing cycle of its offering', async () => {
        const { startTime, endTime } = Billing.billingCycleToTimeRange(validBillingCycles.monthly);

        await service.create(
            buildJob({ businessID: BUSINESS_ID, scheduleParameters: { customerId: CUSTOMER_ID, businessID: null } })
        );

        expect(customerService.findOne).toHaveBeenCalledWith({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID });
        expect(invoicesService.generateInvoiceForUsageTotal).toHaveBeenCalledWith({
            businessID: BUSINESS_ID,
            customerId: CUSTOMER_ID,
            start: startTime,
            end: endTime,
        });
    });

    it('stores a billing record holding the generated invoice id', async () => {
        await service.create(
            buildJob({ businessID: BUSINESS_ID, scheduleParameters: { customerId: CUSTOMER_ID, businessID: null } })
        );

        expect(point.tag).toHaveBeenCalledWith('invoiceId', 'invoice-1');
        expect(point.tag).toHaveBeenCalledWith('customerId', CUSTOMER_ID);
        expect(point.tag).toHaveBeenCalledWith('businessID', BUSINESS_ID);
        expect(influxService.loadPoints).toHaveBeenCalledWith(`${process.env.STAGE}-aggregate-usage`, 'paigo', [point]);
        expect(publishEvent).not.toHaveBeenCalled();
    });

    it('audits a failure instead of storing a partial billing record', async () => {
        const error = new Error('invoice generation blew up');
        invoicesService.generateInvoiceForUsageTotal.mockRejectedValue(error);

        await expect(
            service.create(
                buildJob({ businessID: BUSINESS_ID, scheduleParameters: { customerId: CUSTOMER_ID, businessID: null } })
            )
        ).resolves.toBeUndefined();

        expect(influxService.loadPoints).not.toHaveBeenCalled();
        expect(publishEvent).toHaveBeenCalledWith(
            expect.objectContaining({ topic: AuditScope.ERROR, data: [error] })
        );
    });

    it('does not bill a customer without an offering', async () => {
        customerService.findOne.mockResolvedValue({ data: [{ customerId: CUSTOMER_ID }], message: 'Found Customer' });

        await service.create(
            buildJob({ businessID: BUSINESS_ID, scheduleParameters: { customerId: CUSTOMER_ID, businessID: null } })
        );

        expect(invoicesService.generateInvoiceForUsageTotal).not.toHaveBeenCalled();
        expect(influxService.loadPoints).not.toHaveBeenCalled();
        expect(publishEvent).not.toHaveBeenCalled();
    });
});

