describe('CustomerService billing schedules', () => {
    const BUSINESS_ID = 'myCoolCorp';
    const SUBJECT = 'auth0|1337';
    const OFFERING_ID = 'bc546e8a-3a2c-4089-8133-1efac1759ff5';
    const CUSTOMER_ID = 'b9459f53-054b-4437-8ecd-b6f8070344fc';

    let influxService;
    let schedulerService;
    let service: CustomerService;

    const customerInput = (offeringId?: string): CreateCustomerDto => ({
        customerName: 'Wall Street Trading',
        email: 'matt.sun@paigo.tech',
        paymentChannel: paymentChannel.Stripe,
        paymentChannelOptions: { stripeCustomerId: 'acct-xxxxxxxxxxxxxxxx' },
        businessID: BUSINESS_ID,
        offeringId,
    });

    const expectedSchedule = (customerId: string) => ({
        schedulerID: customerId,
        schedulerType: schedulerType.billing,
        schedulerStatus: SchedulerStatus.live,
        scheduleParameters: { customerId, businessID: BUSINESS_ID },
        rate: SupportedMeasurementFrequencies.monthly,
        subject: SUBJECT,
        businessID: BUSINESS_ID,
    });

    beforeEach(() => {
        const point = { tag: jest.fn(), stringField: jest.fn() };
        influxService = { getPoint: jest.fn(() => point), loadPoints: jest.fn() };
        schedulerService = { create: jest.fn(), remove: jest.fn() };
        service = new CustomerService(
            influxService as unknown as InfluxService,
            schedulerService as unknown as SchedulerService,
            undefined,
            undefined,
            undefined
        );
    });

    it('schedules monthly billing for a new customer with an offering', async () => {
        const { customerId } = await service.create(customerInput(OFFERING_ID), SUBJECT);

        expect(schedulerService.create).toHaveBeenCalledWith(expectedSchedule(customerId));
    });

    it('does not schedule billing for a new customer without an offering', async () => {
        await service.create(customerInput(), SUBJECT);

        expect(schedulerService.create).not.toHaveBeenCalled();
    });

    it('replaces the schedule when a customer gains an offering', async () => {
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: CUSTOMER_ID } as never],
            message: 'Found Customer',
        });

        await service.update({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID }, SUBJECT);

        expect(schedulerService.remove).toHaveBeenCalledWith({
            schedulerID: CUSTOMER_ID,
            businessID: BUSINESS_ID,
            isBillingQueue: true,
        });
        expect(schedulerService.create).toHaveBeenCalledWith(expectedSchedule(CUSTOMER_ID));
    });

    it('replaces the schedule when the offering of a customer changes', async () => {
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: CUSTOMER_ID, offeringId: 'a-previous-offering' } as never],
            message: 'Found Customer',
        });

        await service.update({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID }, SUBJECT);

        expect(schedulerService.remove).toHaveBeenCalledTimes(1);
        expect(schedulerService.create).toHaveBeenCalledWith(expectedSchedule(CUSTOMER_ID));
    });

    it('still schedules billing when there is no previous schedule to remove', async () => {
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: CUSTOMER_ID } as never],
            message: 'Found Customer',
        });
        schedulerService.remove.mockRejectedValue(new NotFoundException('Schedule not found'));

        await expect(
            service.update({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID }, SUBJECT)
        ).resolves.toEqual({ message: 'Customer updated added', customerId: CUSTOMER_ID });
        expect(schedulerService.create).toHaveBeenCalledWith(expectedSchedule(CUSTOMER_ID));
    });

    it('leaves the schedule alone when the offering is unchanged', async () => {
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: CUSTOMER_ID, offeringId: OFFERING_ID } as never],
            message: 'Found Customer',
        });

        await service.update(
            { customerId: CUSTOMER_ID, businessID: BUSINESS_ID, customerName: 'A New Name' },
            SUBJECT
        );
        await service.update({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID }, SUBJECT);

        expect(schedulerService.remove).not.toHaveBeenCalled();
        expect(schedulerService.create).not.toHaveBeenCalled();
    });
});

import { Queue } from 'bull';
import { SchedulerService } from './scheduler.service';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from './dto/scheduler.dto';
import { billingScheduleConsumers } from '../billing/entities/billing.entity';
import { infrastructureType } from '../dimensions/dto/create-dimension.dto';

describe('SchedulerService', () => {
    const BUSINESS_ID = 'myCoolCorp';
    const SCHEDULER_ID = 'e345f409-daca-4144-91d2-0a0f87c96581';
    const CUSTOMER_ID = 'b9459f53-054b-4437-8ecd-b6f8070344fc';

    let queue;
    let billingQueue;
    let service: SchedulerService;

    beforeEach(() => {
        queue = { add: jest.fn().mockResolvedValue({}) };
        billingQueue = { add: jest.fn().mockResolvedValue({}) };
        service = new SchedulerService(queue as unknown as Queue, billingQueue as unknown as Queue);
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    describe('emitOne', () => {
        it('emits a billing measurement on the billing queue for the billing report consumer', async () => {
            await service.emitOne({
                schedulerId: SCHEDULER_ID,
                payload: {
                    schedulerType: schedulerType.billing,
                    schedulerStatus: SchedulerStatus.live,
                    scheduleParameters: { customerId: CUSTOMER_ID, businessID: BUSINESS_ID },
                    rate: SupportedMeasurementFrequencies.monthly,
                    businessID: BUSINESS_ID,
                },
            });

            expect(queue.add).not.toHaveBeenCalled();
            expect(billingQueue.add).toHaveBeenCalledWith(
                billingScheduleConsumers.billingReport,
                expect.objectContaining({
                    schedulerID: SCHEDULER_ID,
                    schedulerType: schedulerType.billing,
                    businessID: BUSINESS_ID,
                    scheduleParameters: { customerId: CUSTOMER_ID, businessID: BUSINESS_ID },
                })
            );
        });

        it('emits every other measurement on the scheduler queue for its dimension consumer', async () => {
            await service.emitOne({
                schedulerId: SCHEDULER_ID,
                payload: {
                    dimensionType: infrastructureType.ebsVolume,
                    schedulerType: schedulerType.dimensionDataGathering,
                    schedulerStatus: SchedulerStatus.live,
                    scheduleParameters: { dimensionType: infrastructureType.ebsVolume },
                    rate: SupportedMeasurementFrequencies.everyHour,
                    businessID: BUSINESS_ID,
                },
            });

            expect(billingQueue.add).not.toHaveBeenCalled();
            expect(queue.add).toHaveBeenCalledWith(
                infrastructureType.ebsVolume,
                expect.objectContaining({ schedulerID: SCHEDULER_ID, businessID: BUSINESS_ID })
            );
        });
    });
});

