describe('UsageService findUsageForCustomer', () => {
    const BUSINESS_ID = 'myCoolCorp';
    const CUSTOMER_ID = 'b9459f53-054b-4437-8ecd-b6f8070344fc';

    let influxService;
    let customerService;
    let service: UsageService;

    beforeEach(() => {
        influxService = { getAggregateUsageForDimension: jest.fn().mockResolvedValue([{ dimensionId: 'dim-1' }]) };
        customerService = { findOne: jest.fn() };
        service = new UsageService(
            influxService as unknown as InfluxService,
            undefined,
            undefined,
            customerService as unknown as CustomerService,
            undefined
        );
    });

    it('returns no usage for a customer without an offering', async () => {
        customerService.findOne.mockResolvedValue({ data: [{ customerId: CUSTOMER_ID }], message: 'Found Customer' });

        await expect(service.findUsageForCustomer({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID }, {})).resolves.toEqual(
            []
        );
        expect(influxService.getAggregateUsageForDimension).not.toHaveBeenCalled();
    });

    it('returns the aggregated usage of the offering of the customer', async () => {
        customerService.findOne.mockResolvedValue({
            data: [{ customerId: CUSTOMER_ID, offering: { offeringId: 'offering-1', dimensions: [] } }],
            message: 'Found Customer',
        });

        await expect(
            service.findUsageForCustomer({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID }, {})
        ).resolves.toEqual([{ dimensionId: 'dim-1' }]);
        expect(influxService.getAggregateUsageForDimension).toHaveBeenCalledWith(
            expect.objectContaining({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID })
        );
    });
});

